  auto*problem=solver->getConstraintProblem();auto*generic=dynamic_cast<sofa::component::constraint::lagrangian::solver::GenericConstraintProblem*>(problem);if(!generic)throw std::runtime_error("public generic constraint problem unavailable");const auto&free=body->read(sofa::core::vec_id::read_access::freePosition)->getValue();const auto&jac=body->read(sofa::core::vec_id::read_access::constraintJacobian)->getValue();std::vector<CoupledContactStep::Plane>planes;double oldSum=0;
